import numpy as np
shapes={'A':[[1,0],[1,1],[1,0]], 'B':[[0,1],[1,1],[0,1]]}
for k,a in shapes.items():
  arr=np.array(a)
  print(k)
  for rot in range(4):
    b=np.rot90(arr,rot)
    for flip in [False,True]:
      c=np.fliplr(b) if flip else b
      inds=np.argwhere(c)
      print(rot,flip,c.shape,inds.tolist())
